      rows: [
        ['本科', '44.69%'],
        ['高中及以下', '32.78%'],
        ['专科', '20.66%'],
        ['硕士', '1.83%'],
        ['博士', '0.04%']
      ]
    },
    {
      x: 0.6, y: 4.30, w: 5.95, h: 2.25,
      title: '人生阶段  LIFE STAGE', sub: '综合身份聚类',
      rows: [
