        ['单身期', '30.43%'],
        ['养育期', '28.86%'],
        ['子女成年期', '3.25%']
      ]
    },
    {
      x: 6.75, y: 4.30, w: 5.95, h: 2.25,
      title: '家户类型  HOUSEHOLD', sub: '综合身份聚类',
      rows: [
        ['Z 世代家户', '65.96%'],
        ['单身小康家户', '31.25%'],
        ['银发家户', '2.48%'],
        ['高品质家户', '0.31%']
      ]
    }
  ];

  cards.forEach((c) => {
