      x: c.x + 0.25, y: c.y + 0.12, w: c.w - 0.4, h: 0.3, fontSize: 12, fontFace: 'PingFang SC',
      color: t.accent1, bold: true, charSpacing: 2
    });
    s.addText(c.sub, {
      x: c.x + 0.25, y: c.y + 0.42, w: c.w - 0.4, h: 0.22, fontSize: 9, fontFace: 'PingFang SC',
