// headline: 服饰主线之外，母婴 / 居家 / 快消共同构成人群生活半径
import pptxgen from 'pptxgenjs';

export function buildSlide(pptx) {
  const t = {
    primary: 'b44626', accent1: '263442', accent2: '5A6675',
    light: 'F7F6F3', ink: '242830', muted: '626773', line: 'DEDCD6'
  };
  const s = pptx.addSlide();
  s.background = { color: 'FFFFFF' };

  // 页眉
  s.addShape('rect', { x: 0.6, y: 0.6, w: 0.08, h: 0.4, fill: { color: t.primary }, line: { type: 'none' } });
  s.addText('05  /  品类偏好', {
    x: 0.85, y: 0.6, w: 8, h: 0.4, fontSize: 11, fontFace: 'PingFang SC',
    color: t.muted, charSpacing: 3, bold: true
  });
  s.addText('SEMIR', {
    x: 11.4, y: 0.6, w: 1.6, h: 0.4, fontSize: 10, fontFace: 'Arial',
    color: t.primary, bold: true, align: 'right', charSpacing: 4
  });

  // 一句话结论（已上移，保留为兜底注释）
  // s.addText('服饰主线之外，母婴 / 居家 / 快消共同构成人群的生活半径', {
  //   x: 0.6, y: 1.15, w: 12.1, h: 0.6, fontSize: 16, fontFace: 'PingFang SC',
  //   color: t.primary, bold: true
  // });

  // 左：完整表格（一级类目 Top 10）
  s.addText('一级类目偏好 Top 10  L1 CATEGORIES', {
    x: 0.6, y: 1.95, w: 6.0, h: 0.3, fontSize: 11, fontFace: 'PingFang SC',
    color: t.accent1, bold: true, charSpacing: 2
  });

  // 表头
  const tableX = 0.6, tableY = 2.3, colW1 = 4.3, colW2 = 1.5;
  s.addShape('rect', { x: tableX, y: tableY, w: colW1 + colW2, h: 0.36, fill: { color: t.accent1 }, line: { type: 'none' } });
  s.addText('类目', { x: tableX + 0.15, y: tableY, w: colW1, h: 0.36, fontSize: 10.5, fontFace: 'PingFang SC', color: 'FFFFFF', bold: true, valign: 'middle' });
  s.addText('占比', { x: tableX + colW1, y: tableY, w: colW2, h: 0.36, fontSize: 10.5, fontFace: 'PingFang SC', color: 'FFFFFF', bold: true, valign: 'middle', align: 'right' });

  const top1 = [
    ['运动鞋', '7.5%'],
    ['运动服 / 休闲服装', '7.23%'],
    ['箱包皮具 / 热销女包 / 男包', '6.95%'],
    ['珠宝 / 钻石 / 翡翠 / 黄金', '5.84%'],
    ['咖啡 / 麦片 / 冲饮', '5.41%'],
    ['美容护肤 / 美体 / 精油', '4.94%'],
    ['女士内衣 / 男士内衣 / 家居服', '4.82%'],
    ['女装 / 女士精品', '4.78%'],
    ['童装 / 婴儿装 / 亲子装', '4.75%'],
    ['童鞋 / 婴儿鞋 / 亲子鞋', '4.71%']
  ];

  let ry = tableY + 0.36;
  top1.forEach((row, i) => {
    if (i % 2 === 0) {
      s.addShape('rect', { x: tableX, y: ry, w: colW1 + colW2, h: 0.32, fill: { color: t.light }, line: { type: 'none' } });
    }
    s.addText(row[0], {
      x: tableX + 0.15, y: ry, w: colW1 - 0.2, h: 0.32, fontSize: 10, fontFace: 'PingFang SC',
      color: t.ink, valign: 'middle'
    });
    s.addText(row[1], {
      x: tableX + colW1, y: ry, w: colW2 - 0.15, h: 0.32, fontSize: 10, fontFace: 'Arial',
      color: i < 3 ? t.primary : t.ink, bold: i < 3, valign: 'middle', align: 'right'
    });
    ry += 0.32;
  });

  // 中：二级类目 Top 8（表格）
  s.addText('二级类目偏好 Top 8  L2 CATEGORIES', {
    x: 6.9, y: 1.95, w: 6.0, h: 0.3, fontSize: 11, fontFace: 'PingFang SC',
    color: t.accent1, bold: true, charSpacing: 2
  });

  const t2x = 6.9, t2y = 2.3, t2w1 = 3.8, t2w2 = 1.6;
  s.addShape('rect', { x: t2x, y: t2y, w: t2w1 + t2w2, h: 0.36, fill: { color: t.accent1 }, line: { type: 'none' } });
  s.addText('类目', { x: t2x + 0.15, y: t2y, w: t2w1, h: 0.36, fontSize: 10.5, fontFace: 'PingFang SC', color: 'FFFFFF', bold: true, valign: 'middle' });
  s.addText('占比', { x: t2x + t2w1, y: t2y, w: t2w2, h: 0.36, fontSize: 10.5, fontFace: 'PingFang SC', color: 'FFFFFF', bold: true, valign: 'middle', align: 'right' });

  const top2 = [
    ['运动休闲鞋', '6.87%'],
    ['牛仔裤', '6.04%'],
    ['羽绒服', '5.52%'],
    ['女士包袋', '5.42%'],
    ['板鞋', '5.4%'],
    ['运动羽绒服', '5.39%'],
    ['半身裙', '5.37%'],
    ['毛针织衫', '5.24%']

